-- Typed revenue, employee payroll, bilateral transactions and tax subledgers.
-- A confirmed business fact produces a pending accounting source, never an automatic posting.
CREATE TABLE fb_command(tenant_id uuid NOT NULL,request_id uuid NOT NULL,resource_id uuid NOT NULL,operation varchar(50) NOT NULL,request_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,request_id));
CREATE TABLE fb_revenue_batch(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,source varchar(20) NOT NULL CHECK(source IN ('PMS','OTA','CUSTOMER','CHANNEL')),
 channel varchar(100) NOT NULL,business_date date NOT NULL,night_audit_date date NOT NULL,revision integer NOT NULL CHECK(revision>0),
 expected_count integer NOT NULL CHECK(expected_count>0),control_total numeric(18,2) NOT NULL CHECK(control_total>=0),source_reference varchar(240) NOT NULL,
 status varchar(20) NOT NULL DEFAULT 'REVIEW' CHECK(status IN ('REVIEW','CONFIRMED','SUPERSEDED','CANCELLED')),source_hash char(64) NOT NULL,created_by uuid NOT NULL,reviewer_id uuid NOT NULL,confirmed_by uuid,version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,hotel_id,source,channel,business_date,revision),FOREIGN KEY(tenant_id,hotel_id) REFERENCES org_unit(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES finance_company(tenant_id,id),CHECK(created_by<>reviewer_id)
);
CREATE INDEX fb_revenue_batch_scope ON fb_revenue_batch(tenant_id,hotel_id,business_date);
CREATE TABLE fb_revenue_entry(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,batch_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,external_id varchar(160) NOT NULL,
 kind varchar(20) NOT NULL CHECK(kind IN ('INCOME','AR','DEPOSIT','PREPAYMENT','STORED_VALUE')),customer varchar(160) NOT NULL,channel varchar(100) NOT NULL,due_date date NOT NULL,
 amount numeric(18,2) NOT NULL CHECK(amount>0),net_amount numeric(18,2) NOT NULL CHECK(net_amount>=0),tax_amount numeric(18,2) NOT NULL CHECK(tax_amount>=0),commission numeric(18,2) NOT NULL CHECK(commission>=0),fee numeric(18,2) NOT NULL CHECK(fee>=0),
 active boolean NOT NULL DEFAULT false,previous_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,batch_id,external_id),
 FOREIGN KEY(tenant_id,batch_id) REFERENCES fb_revenue_batch(tenant_id,id),FOREIGN KEY(tenant_id,previous_id) REFERENCES fb_revenue_entry(tenant_id,id),CHECK(amount=net_amount+tax_amount),CHECK(commission+fee<=amount)
);
CREATE INDEX fb_revenue_entry_scope ON fb_revenue_entry(tenant_id,hotel_id,active,due_date);
CREATE TABLE fb_revenue_movement(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,entry_id uuid NOT NULL,related_entry_id uuid,kind varchar(16) NOT NULL CHECK(kind IN ('RECEIPT','REFUND','REDEEM','ADJUSTMENT')),amount numeric(18,2) NOT NULL CHECK(amount>0),occurred_on date NOT NULL,
 bank_reference varchar(240) NOT NULL,note varchar(2000) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,entry_id) REFERENCES fb_revenue_entry(tenant_id,id),FOREIGN KEY(tenant_id,related_entry_id) REFERENCES fb_revenue_entry(tenant_id,id),CHECK((kind='REDEEM')=(related_entry_id IS NOT NULL))
);
CREATE TABLE fb_payroll_batch(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,month date NOT NULL,source_reference varchar(240) NOT NULL,supplements_id uuid,
 gross_amount numeric(18,2) NOT NULL,deduction_amount numeric(18,2) NOT NULL,net_amount numeric(18,2) NOT NULL,employer_amount numeric(18,2) NOT NULL,
 status varchar(16) NOT NULL DEFAULT 'REVIEW' CHECK(status IN ('REVIEW','CONFIRMED','CANCELLED')),created_by uuid NOT NULL,reviewer_id uuid NOT NULL,cashier_id uuid NOT NULL,confirmed_by uuid,version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,hotel_id) REFERENCES org_unit(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES finance_company(tenant_id,id),FOREIGN KEY(tenant_id,supplements_id) REFERENCES fb_payroll_batch(tenant_id,id),CHECK(created_by<>reviewer_id AND created_by<>cashier_id),CHECK(net_amount=gross_amount-deduction_amount AND net_amount>=0)
);
CREATE UNIQUE INDEX fb_payroll_primary_month ON fb_payroll_batch(tenant_id,hotel_id,month) WHERE supplements_id IS NULL AND status<>'CANCELLED';
CREATE TABLE fb_payroll_line(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,batch_id uuid NOT NULL,employee_id uuid NOT NULL,department_id uuid NOT NULL,earnings jsonb NOT NULL,deductions jsonb NOT NULL,employer_costs jsonb NOT NULL,
 gross_amount numeric(18,2) NOT NULL,deduction_amount numeric(18,2) NOT NULL,net_amount numeric(18,2) NOT NULL,employer_amount numeric(18,2) NOT NULL,
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,batch_id,employee_id),FOREIGN KEY(tenant_id,batch_id) REFERENCES fb_payroll_batch(tenant_id,id),FOREIGN KEY(tenant_id,employee_id) REFERENCES user_account(tenant_id,id),FOREIGN KEY(tenant_id,department_id) REFERENCES org_unit(tenant_id,id),CHECK(net_amount=gross_amount-deduction_amount AND net_amount>=0)
);
CREATE TABLE fb_payroll_payment(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,line_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),occurred_on date NOT NULL,bank_reference varchar(240) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,bank_reference),FOREIGN KEY(tenant_id,line_id) REFERENCES fb_payroll_line(tenant_id,id));
CREATE INDEX fb_payroll_scope ON fb_payroll_batch(tenant_id,hotel_id,month);
CREATE TABLE fb_intercompany(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,counterparty_hotel_id uuid NOT NULL,counterparty_company_id uuid NOT NULL,
 month date NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN ('ADVANCE','SERVICE','ALLOCATION')),amount numeric(18,2) NOT NULL CHECK(amount>0),basis_reference varchar(240) NOT NULL,basis_snapshot jsonb NOT NULL,
 creator_id uuid NOT NULL,reviewer_id uuid NOT NULL,counterparty_reviewer_id uuid NOT NULL,confirmed_by uuid,counterparty_confirmed_by uuid,
 status varchar(20) NOT NULL DEFAULT 'REVIEW' CHECK(status IN ('REVIEW','CONFIRMED','CANCELLED')),version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),
 FOREIGN KEY(tenant_id,hotel_id) REFERENCES org_unit(tenant_id,id),FOREIGN KEY(tenant_id,counterparty_hotel_id) REFERENCES org_unit(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES finance_company(tenant_id,id),FOREIGN KEY(tenant_id,counterparty_company_id) REFERENCES finance_company(tenant_id,id),CHECK(hotel_id<>counterparty_hotel_id),CHECK(creator_id<>reviewer_id AND creator_id<>counterparty_reviewer_id AND reviewer_id<>counterparty_reviewer_id)
);
CREATE TABLE fb_consolidation_scope(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(160) NOT NULL,version integer NOT NULL,hotel_ids jsonb NOT NULL,rules jsonb NOT NULL,created_by uuid NOT NULL,published_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name,version));
CREATE TABLE fb_intercompany_settlement(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,transaction_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,side varchar(16) NOT NULL CHECK(side IN ('ORIGIN','COUNTERPARTY')),kind varchar(8) NOT NULL CHECK(kind IN ('RECEIPT','PAYMENT')),amount numeric(18,2) NOT NULL CHECK(amount>0),occurred_on date NOT NULL,bank_reference varchar(240) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,bank_reference),FOREIGN KEY(tenant_id,transaction_id) REFERENCES fb_intercompany(tenant_id,id));
CREATE INDEX fb_intercompany_settlement_source ON fb_intercompany_settlement(tenant_id,transaction_id,side,occurred_on);
CREATE TABLE fb_consolidation_worksheet(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,scope_id uuid NOT NULL,month date NOT NULL,source_hash char(64) NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,scope_id,month,source_hash),FOREIGN KEY(tenant_id,scope_id) REFERENCES fb_consolidation_scope(tenant_id,id));
CREATE TABLE fb_output_request(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,buyer_name varchar(160) NOT NULL,buyer_tax_number varchar(80) NOT NULL,status varchar(24) NOT NULL DEFAULT 'WAIT_EXTERNAL' CHECK(status IN ('WAIT_EXTERNAL','REGISTERED','CANCELLED')),created_by uuid NOT NULL,version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES finance_company(tenant_id,id));
CREATE TABLE fb_output_line(tenant_id uuid NOT NULL,request_id uuid NOT NULL,entry_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),PRIMARY KEY(tenant_id,request_id,entry_id),FOREIGN KEY(tenant_id,request_id) REFERENCES fb_output_request(tenant_id,id),FOREIGN KEY(tenant_id,entry_id) REFERENCES fb_revenue_entry(tenant_id,id));
CREATE TABLE fb_output_invoice(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,request_id uuid NOT NULL,invoice_code varchar(40) NOT NULL,invoice_number varchar(80) NOT NULL,net_amount numeric(18,2) NOT NULL CHECK(net_amount>=0),tax_amount numeric(18,2) NOT NULL CHECK(tax_amount>=0),issued_on date NOT NULL,red_of uuid,attachment_id uuid NOT NULL,external_reference varchar(240) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,invoice_code,invoice_number),FOREIGN KEY(tenant_id,request_id) REFERENCES fb_output_request(tenant_id,id),FOREIGN KEY(tenant_id,red_of) REFERENCES fb_output_invoice(tenant_id,id));
CREATE TABLE fb_input_tax(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,invoice_id uuid NOT NULL,month date NOT NULL,purpose varchar(100) NOT NULL,eligible_tax numeric(18,2) NOT NULL CHECK(eligible_tax>=0),claimed_tax numeric(18,2) NOT NULL CHECK(claimed_tax>=0),transfer_out numeric(18,2) NOT NULL CHECK(transfer_out>=0),policy_id uuid NOT NULL,note varchar(2000) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id) REFERENCES finance_company(tenant_id,id),CHECK(claimed_tax<=eligible_tax));
CREATE INDEX fb_input_tax_invoice ON fb_input_tax(tenant_id,invoice_id,month);
CREATE TABLE fb_tax_policy(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,name varchar(160) NOT NULL,version integer NOT NULL,effective_from date NOT NULL,effective_until date NOT NULL,official_reference varchar(1000) NOT NULL,fields jsonb NOT NULL,created_by uuid NOT NULL,published_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,company_id,name,version),CHECK(effective_until>=effective_from));
CREATE TABLE fb_tax_return(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,month date NOT NULL,policy_id uuid NOT NULL,source_hash char(64) NOT NULL,snapshot jsonb NOT NULL,declared_amount numeric(18,2),explanation varchar(2000) NOT NULL DEFAULT '',created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,policy_id) REFERENCES fb_tax_policy(tenant_id,id));
CREATE TABLE fb_tax_receipt(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,return_id uuid NOT NULL,kind varchar(16) NOT NULL CHECK(kind IN ('FILING','PAYMENT')),external_reference varchar(240) NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),attachment_id uuid NOT NULL,occurred_on date NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,external_reference,kind),FOREIGN KEY(tenant_id,return_id) REFERENCES fb_tax_return(tenant_id,id));
CREATE TABLE fb_attachment(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,domain varchar(24) NOT NULL,resource_id uuid NOT NULL,hotel_id uuid NOT NULL,original_name varchar(180) NOT NULL,media_type varchar(100) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 20971520),sha256 char(64) NOT NULL,object_key varchar(240) NOT NULL,scan_status varchar(40) NOT NULL,uploaded_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,object_key));
CREATE TABLE fb_opening_clearing(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,subledger_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,kind varchar(8) NOT NULL CHECK(kind IN ('RECEIPT','PAYMENT')),amount numeric(18,2) NOT NULL CHECK(amount>0),occurred_on date NOT NULL,bank_reference varchar(240) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,bank_reference));
CREATE INDEX fb_opening_clearing_source ON fb_opening_clearing(tenant_id,subledger_id,occurred_on);
CREATE TABLE fb_bank_match(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,transaction_id uuid NOT NULL,source_type varchar(16) NOT NULL CHECK(source_type IN ('REVENUE','PAYROLL','OPENING','INTERCOMPANY')),source_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),request_id uuid NOT NULL,note varchar(2000) NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,request_id,source_type,source_id),FOREIGN KEY(tenant_id,transaction_id) REFERENCES fo_bank_transaction(tenant_id,id));
CREATE INDEX fb_bank_match_transaction ON fb_bank_match(tenant_id,transaction_id);
CREATE INDEX fb_bank_match_source ON fb_bank_match(tenant_id,source_type,source_id);
CREATE TABLE fb_cash_correction(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,source_type varchar(16) NOT NULL CHECK(source_type IN ('REVENUE','PAYROLL','OPENING','INTERCOMPANY')),source_id uuid NOT NULL,hotel_id uuid NOT NULL,company_id uuid NOT NULL,original_kind varchar(16) NOT NULL,original_source_event_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),business_date date NOT NULL,accounting_on date NOT NULL,note varchar(2000) NOT NULL,proof jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,original_source_event_id) REFERENCES fa_source_event(tenant_id,id),CHECK(accounting_on>=business_date));
CREATE INDEX fb_cash_correction_source ON fb_cash_correction(tenant_id,source_type,source_id,accounting_on);
CREATE TABLE fb_bank_match_reversal(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,match_id uuid NOT NULL,correction_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),accounting_on date NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,match_id,correction_id),FOREIGN KEY(tenant_id,match_id) REFERENCES fb_bank_match(tenant_id,id),FOREIGN KEY(tenant_id,correction_id) REFERENCES fb_cash_correction(tenant_id,id));
CREATE INDEX fb_bank_match_reversal_source ON fb_bank_match_reversal(tenant_id,match_id,accounting_on);
-- SECURITY INVOKER (the default) deliberately preserves the caller's forced tenant RLS.
CREATE FUNCTION fb_cash_effective_amount(t uuid,k text,s uuid,original numeric,as_of date) RETURNS numeric LANGUAGE sql STABLE AS $$ SELECT original-coalesce(sum(amount),0) FROM fb_cash_correction WHERE tenant_id=t AND source_type=k AND source_id=s AND accounting_on<=as_of $$;
CREATE FUNCTION fb_bank_matched_amount(t uuid,k text,s uuid,as_of date) RETURNS numeric LANGUAGE sql STABLE AS $$ SELECT coalesce(sum(m.amount-coalesce((SELECT sum(r.amount) FROM fb_bank_match_reversal r WHERE r.tenant_id=m.tenant_id AND r.match_id=m.id AND r.accounting_on<=as_of),0)),0) FROM fb_bank_match m WHERE m.tenant_id=t AND m.source_type=k AND m.source_id=s AND (m.created_at AT TIME ZONE 'Asia/Shanghai')::date<=as_of $$;
CREATE FUNCTION fb_bank_allocated_amount(t uuid,b uuid,as_of date) RETURNS numeric LANGUAGE sql STABLE AS $$ SELECT coalesce(sum(m.amount-coalesce((SELECT sum(r.amount) FROM fb_bank_match_reversal r WHERE r.tenant_id=m.tenant_id AND r.match_id=m.id AND r.accounting_on<=as_of),0)),0) FROM fb_bank_match m WHERE m.tenant_id=t AND m.transaction_id=b AND (m.created_at AT TIME ZONE 'Asia/Shanghai')::date<=as_of $$;
CREATE FUNCTION fb_revenue_redeemed_into(t uuid,s uuid,as_of date) RETURNS numeric LANGUAGE sql STABLE AS $$ SELECT coalesce(sum(fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,as_of)),0) FROM fb_revenue_movement m JOIN fb_revenue_entry e ON e.tenant_id=m.tenant_id AND e.id=m.related_entry_id JOIN fb_revenue_batch b ON b.tenant_id=e.tenant_id AND b.id=e.batch_id JOIN fb_revenue_entry current_entry ON current_entry.tenant_id=e.tenant_id AND current_entry.id=s JOIN fb_revenue_batch current_batch ON current_batch.tenant_id=current_entry.tenant_id AND current_batch.id=current_entry.batch_id WHERE m.tenant_id=t AND m.kind='REDEEM' AND m.occurred_on<=as_of AND e.hotel_id=current_entry.hotel_id AND e.external_id=current_entry.external_id AND b.source=current_batch.source AND b.channel=current_batch.channel AND b.business_date=current_batch.business_date $$;
CREATE INDEX fb_attachment_resource ON fb_attachment(tenant_id,domain,resource_id);
CREATE INDEX fb_intercompany_scope ON fb_intercompany(tenant_id,hotel_id,counterparty_hotel_id,month);
CREATE INDEX fb_output_scope ON fb_output_request(tenant_id,hotel_id,status);
CREATE INDEX fb_input_scope ON fb_input_tax(tenant_id,hotel_id,month);
CREATE INDEX fb_tax_return_scope ON fb_tax_return(tenant_id,hotel_id,month);
CREATE FUNCTION fb_protect_reviewed_fact() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='fb_revenue_entry' THEN
  IF (to_jsonb(NEW)-'active') IS DISTINCT FROM (to_jsonb(OLD)-'active') THEN RAISE EXCEPTION 'Revenue source fields are immutable; create a new revision'; END IF;
 ELSIF TG_TABLE_NAME IN ('fb_revenue_batch','fb_payroll_batch') THEN
  IF (to_jsonb(NEW)-'status'-'confirmed_by'-'version') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'confirmed_by'-'version') THEN RAISE EXCEPTION 'Financial source batch is immutable'; END IF;
 ELSIF TG_TABLE_NAME='fb_intercompany' THEN
  IF (to_jsonb(NEW)-'status'-'confirmed_by'-'counterparty_confirmed_by'-'version') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'confirmed_by'-'counterparty_confirmed_by'-'version') THEN RAISE EXCEPTION 'Bilateral basis is immutable'; END IF;
 ELSIF TG_TABLE_NAME IN ('fb_tax_policy','fb_consolidation_scope') THEN
  IF (to_jsonb(NEW)-'published_by') IS DISTINCT FROM (to_jsonb(OLD)-'published_by') OR OLD.published_by IS NOT NULL AND NEW.published_by IS DISTINCT FROM OLD.published_by THEN RAISE EXCEPTION 'Published financial policy is immutable'; END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER fb_revenue_entry_protection BEFORE UPDATE ON fb_revenue_entry FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
CREATE TRIGGER fb_revenue_batch_protection BEFORE UPDATE ON fb_revenue_batch FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
CREATE TRIGGER fb_payroll_batch_protection BEFORE UPDATE ON fb_payroll_batch FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
CREATE TRIGGER fb_intercompany_protection BEFORE UPDATE ON fb_intercompany FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
CREATE TRIGGER fb_tax_policy_protection BEFORE UPDATE ON fb_tax_policy FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
CREATE TRIGGER fb_consolidation_scope_protection BEFORE UPDATE ON fb_consolidation_scope FOR EACH ROW EXECUTE FUNCTION fb_protect_reviewed_fact();
DO $$ DECLARE tab text; BEGIN
 FOREACH tab IN ARRAY ARRAY['fb_command','fb_revenue_batch','fb_revenue_entry','fb_revenue_movement','fb_payroll_batch','fb_payroll_line','fb_payroll_payment','fb_intercompany','fb_intercompany_settlement','fb_consolidation_scope','fb_consolidation_worksheet','fb_output_request','fb_output_line','fb_output_invoice','fb_input_tax','fb_tax_policy','fb_tax_return','fb_tax_receipt','fb_attachment','fb_bank_match','fb_opening_clearing','fb_cash_correction','fb_bank_match_reversal'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tab);
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='hotel_ai_os_app') THEN EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO hotel_ai_os_app',tab);EXECUTE format('REVOKE DELETE ON %I FROM hotel_ai_os_app',tab);END IF;
 END LOOP;
 FOREACH tab IN ARRAY ARRAY['fb_command','fb_revenue_movement','fb_payroll_line','fb_payroll_payment','fb_intercompany_settlement','fb_consolidation_worksheet','fb_output_line','fb_output_invoice','fb_input_tax','fb_tax_return','fb_tax_receipt','fb_attachment','fb_bank_match','fb_opening_clearing','fb_cash_correction','fb_bank_match_reversal'] LOOP
  EXECUTE format('CREATE TRIGGER fb_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_store_resource_fact_mutation()',tab);
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='hotel_ai_os_app') THEN EXECUTE format('REVOKE UPDATE ON %I FROM hotel_ai_os_app',tab);END IF;
 END LOOP;
END $$;
